        walk(h, [[k], v])
        k.ir_type == "String"
        v.ir_type == "String"
        has_credential_keyword(k.value)
        count(v.value) > 0
        not is_variable_reference_pattern(v.value)
        r := {"key": k, "value": v, "path": path}
    }
}

# Main detection: find any string value with credential keyword in name
detect_credential_field(node, path) = result {
    # Direct key-value with string value
    node.ir_type == "Hash"
    some k, v
    walk(node.value, [[k], v])
    k.ir_type == "String"
    v.ir_type == "String"
    has_credential_keyword(k.value)
    is_hardcoded_string(v)
    not has_external_reference(v)
    result := {"key": k, "value": v, "path": path}
}

detect_credential_field(node, path) = result {
