check_variable_value(var_name, value, path) = result {
    value.ir_type == "Hash"
    some k, v
    walk(value.value, [[k], v])
    k.ir_type == "String"
    full_path := sprintf("%s.%s", [var_name, k.value])
    r := check_variable_value(full_path, v, path)
